  LuaManager.env.rawset("__case",System.getProperty("sao.electrical.case","normal"));load(unit.resolve("electrical_ordinary_ports.lua"));load(unit.resolve("electrical_ordinary_cases.lua"));String consumerHook=System.getProperty("sao.d6.consumerScript");if(consumerHook!=null&&System.getProperty("sao.d6.control","none").equals("none")){System.out.println("CHIEF_CONSUMER_HOOK "+consumerHook);load(Path.of(consumerHook));}System.exit(0);
